SELECT w.waterregistry, w.watereqref, w.waterlevelpercent, w.waterqualityindex, w.wastetanklevelpercent, 
       w.waterlevelpercent * (CAST(w.waterqualityindex AS numeric) / 100) * (1 - w.wastetanklevelpercent / 100) AS wrmi
FROM waterandwaste w LIMIT 5;

SELECT COUNT(*) FROM (
    SELECT l.stationname, l.locationtype as zonetype
    FROM waterandwaste w
    JOIN location l ON w.watereqref = l.loceqref
    GROUP BY l.stationname, l.locationtype
) sub;

-- Check if there might be a different interpretation
-- Perhaps waterqualityindex is already 0-100 scale when used in WRMI
SELECT MIN(waterqualityindex), MAX(waterqualityindex), AVG(waterqualityindex) FROM waterandwaste;

-- Check if all watereqref values exist in location.loceqref
SELECT COUNT(*) FROM waterandwaste w 
WHERE NOT EXISTS (SELECT 1 FROM location l WHERE l.loceqref = w.watereqref);

